100	// ========== 哈希函数 ==========
101	function hashCode(str) {
102	  var hash = 5381
103	  for (var i = 0; i < str.length; i++) {
104	    hash = (hash * 33) ^ str.charCodeAt(i)
105	  }
106	  return hash >>> 0
107	}
