717	  /**
718	   * 从二进制文件加载 Block（新格式）
719	   * 文件格式：BLOK (4B) | version (4B) | chunkId (4B) | bucketCount (2B) | [bucketIndex (2B) | idCount (2B) | ids (idCount×4B)] ...
720	   */
721	  _loadChunkFromFileBinary(chunkId) {
722	    return new Promise(function(resolve) {
723	      try {
724	        var file = require('@system.file')
725	        var blockPath = this.basePath + this.config.files.blockPrefix + chunkId + this.config.files.blockSuffix
726	        var chunkConfig = this.chunks[chunkId]
727	        
728	        if (!chunkConfig) {
729	          _logWarn('块 ' + chunkId + ' 配置不存在', 'chunk')
730	          resolve(null)
731	          return
732	        }
733	        
734	        file.readArrayBuffer({
735	          uri: blockPath,
736	          success: function(res) {
737	            try {
738	              // ========== 关键修复：手动转换类数组为 ArrayBuffer ==========
739	              var arrayLike = res.buffer
740	              var buffer = new ArrayBuffer(arrayLike.length)
741	              var uint8View = new Uint8Array(buffer)
742	              for (var i = 0; i < arrayLike.length; i++) {
743	                uint8View[i] = arrayLike[i] & 0xFF
744	              }
745	              
746	              var dv = new DataView(buffer)
747	              var offset = 0
748	              
749	              // 读取头部
750	              var magic = dv.getUint32(offset, true)
751	              offset += 4
752	              var version = dv.getUint32(offset, true)
753	              offset += 4
754	              var chunkIdRead = dv.getUint32(offset, true)
755	              offset += 4
756	              // 验证 Magic
757	              if (magic !== 0x424C4F4B) {
758	                _logError('块 ' + chunkId + ' Magic 不匹配: 0x' + magic.toString(16), 'chunk')
759	                resolve(null)
760	                return
761	              }
762	              
763	              if (version !== 1) {
764	                _logWarn('块 ' + chunkId + ' 版本不匹配: ' + version + '，尝试文本格式', 'chunk')
765	                this._loadChunkFromFileText(chunkId).then(resolve)
766	                return
767	              }
768	              
769	              var bucketCount = dv.getUint16(offset, true)
770	              offset += 2
771	              
772	              var chunkData = {
773	                chunkId: chunkIdRead,
774	                bucketStart: chunkConfig.bucketStart,
775	                bucketEnd: chunkConfig.bucketEnd,
776	                recordCount: 0,
777	                buckets: {}
778	              }
779	              
780	              for (var i = 0; i < bucketCount; i++) {
781	                if (offset + 4 > buffer.byteLength) {
782	                  _logError('块 ' + chunkId + ' 数据截断', 'chunk')
783	                  resolve(null)
784	                  return
785	                }
786	                var bucketIndex = dv.getUint16(offset, true)
787	                offset += 2
788	                var idCount = dv.getUint16(offset, true)
789	                offset += 2
790	                
791	                if (offset + idCount * 4 > buffer.byteLength) {
792	                  _logError('块 ' + chunkId + ' ID数据截断', 'chunk')
793	                  resolve(null)
794	                  return
795	                }
796	                
797	                var ids = []
798	                for (var j = 0; j < idCount; j++) {
799	                  ids.push(dv.getUint32(offset, true))
800	                  offset += 4
801	                }
802	                chunkData.buckets[bucketIndex] = ids
803	                chunkData.recordCount += idCount
804	              }
805	              
806	              _logInfo('块 ' + chunkId + ' 从二进制文件加载完成，' + chunkData.recordCount + ' 条', 'chunk')
807	              resolve(chunkData)
808	            } catch(e) {
809	              _logError('块 ' + chunkId + ' 二进制解析失败: ' + e.message + '，尝试文本格式', 'chunk')
810	              this._loadChunkFromFileText(chunkId).then(resolve)
811	            }
812	          }.bind(this),
813	          fail: function(err, code) {
814	            _logWarn('块 ' + chunkId + ' 二进制文件读取失败: code=' + code + '，尝试文本格式', 'chunk')
815	            this._loadChunkFromFileText(chunkId).then(resolve)
816	          }.bind(this)
817	        })
818	      } catch(e) {
819	        _logError('_loadChunkFromFileBinary异常: ' + e.message, 'chunk')
820	        this._loadChunkFromFileText(chunkId).then(resolve)
821	      }
822	    }.bind(this))
823	  }
