// gRPC 模拟点击和滑动
const grpc = require('@grpc/grpc-js');
const protoLoader = require('@grpc/proto-loader');
const path = require('path');

const protoPath = path.join(__dirname, 'node_modules/@aiot-toolkit/emulator/lib/static/proto/emulator_controller.proto');
const pkg = protoLoader.loadSync(protoPath, { keepCase: true, longs: String, enums: String, defaults: true, oneofs: true });
const controller = grpc.loadPackageDefinition(pkg).android.emulation.control;
const port = process.argv[2] || '8554';
const client = new controller.EmulatorController(`127.0.0.1:${port}`, grpc.credentials.createInsecure());

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
function mouse(x, y, buttons) {
  return new Promise((resolve, reject) => {
    client.sendMouse({ x, y, buttons }, (err) => err ? reject(err) : resolve());
  });
}

async function tap(x, y) {
  await mouse(x, y, 1);
  await sleep(50);
  await mouse(x, y, 0);
  await sleep(400);
  console.log('tap', x, y);
}

async function swipe(x, y1, y2) {
  await mouse(x, y1, 1);
  for (let i = 1; i <= 10; i++) {
    const y = y1 + (y2 - y1) * i / 10;
    await mouse(x, y, 1);
    await sleep(16);
  }
  await mouse(x, y2, 0);
  await sleep(400);
  console.log('swipe', y1, '->', y2);
}

// 命令行：node tap.js <port> tap <x> <y>   或   node tap.js <port> swipe <y1> <y2>
const cmd = process.argv[3];
if (cmd === 'tap') {
  tap(Number(process.argv[4]), Number(process.argv[5])).then(() => process.exit(0));
} else if (cmd === 'swipe') {
  swipe(168, Number(process.argv[4]), Number(process.argv[5])).then(() => process.exit(0));
} else {
  console.log('usage: node tap.js <port> tap <x> <y> | swipe <y1> <y2>');
  process.exit(1);
}

